+       slot->magic = VCQ_CMD_MAGIC;
+       slot->id = VCQ_CMD_ID(core_id, 0, 1, cmd_id);
+       slot->hwc.qse.cmd_ml_kem_keygen.k = k;
+       slot->hwc.qse.cmd_ml_kem_keygen.flags = flags;
+       slot->hwc.qse.cmd_ml_kem_keygen.seed = seed;
