+ * @masked: Use masked (side-channel protected) variant
+ */
+void vcq_add_qse_ml_kem_enc(struct vcq_cmd *slot, u32 core_id, u32 k, u32 flags,
+                           u64 coin, u64 ek, u64 ct, u64 ss, u32 ss_type,
