+       slot->hwc.pke.cmd_sm2_ecdh_hash.id_digest = dig_dma;
+       slot->hwc.pke.cmd_sm2_ecdh_hash.shared_point = sp_ref;
+       slot->hwc.pke.cmd_sm2_ecdh_hash.shared_key = sk_ref;
